package dominoes

// Domino represents a single domino with two numbered sides.
type Domino [2]int

// MakeChain attempts to arrange the given dominoes into a closed chain
// where adjacent halves match and the outer halves of the ends match too.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}

	used := make([]bool, len(input))
	chain := make([]Domino, 0, len(input))

	var search func(end int) bool
	search = func(end int) bool {
		if len(chain) == len(input) {
			return chain[0][0] == end
		}
		for i, d := range input {
			if used[i] {
				continue
			}
			// try normal orientation
			if d[0] == end {
				used[i] = true
				chain = append(chain, Domino{d[0], d[1]})
				if search(d[1]) {
					return true
				}
				chain = chain[:len(chain)-1]
				used[i] = false
			}
			// try reversed orientation
			if d[1] == end && d[0] != d[1] {
				used[i] = true
				chain = append(chain, Domino{d[1], d[0]})
				if search(d[0]) {
					return true
				}
				chain = chain[:len(chain)-1]
				used[i] = false
			}
		}
		return false
	}

	// Try each domino as the first one (in both orientations).
	for i, d := range input {
		used[i] = true
		chain = append(chain, Domino{d[0], d[1]})
		if search(d[1]) {
			return chain, true
		}
		chain = chain[:len(chain)-1]
		if d[0] != d[1] {
			chain = append(chain, Domino{d[1], d[0]})
			if search(d[0]) {
				return chain, true
			}
			chain = chain[:len(chain)-1]
		}
		used[i] = false
	}

	return nil, false
}
